package com.salam.androidwebserver;

import android.app.*;
import android.content.*;
import android.net.*;
import android.os.*;
import java.io.*;
import java.net.*;
import java.nio.charset.StandardCharsets;
import java.text.SimpleDateFormat;
import java.util.*;
import java.util.concurrent.*;

public class WebServerService extends Service {
    public static volatile boolean running=false;
    public static volatile long requests=0;
    public static final Set<String> clients=ConcurrentHashMap.newKeySet();
    static final List<String> LOGS=Collections.synchronizedList(new ArrayList<String>());
    static final ConcurrentHashMap<String,ArrayDeque<Long>> RATE=new ConcurrentHashMap<>();
    static ServerSocket socket; static long startedAt;

    SharedPreferences pref(){return getSharedPreferences("server",MODE_PRIVATE);}
    public static File webRoot(Context c){File f=new File(c.getFilesDir(),"www");if(!f.exists())f.mkdirs();File i=new File(f,"index.html");if(!i.exists())try(FileWriter w=new FileWriter(i)){w.write(defaultPage());}catch(Exception ignored){}return f;}
    static String defaultPage(){return "<!doctype html><html><head><meta name='viewport' content='width=device-width,initial-scale=1'><title>Salam Web Server</title></head><body style='margin:0;background:#03101f;color:#f6f9ff;font-family:Arial,sans-serif'><div style='min-height:100vh;padding:24px;box-sizing:border-box;background:linear-gradient(145deg,#03101f,#071b33)'><div style='max-width:760px;margin:auto'><div style='display:flex;align-items:center;gap:12px;font-size:22px;font-weight:700'><span style='color:#1bd3ff'>▰</span>Salam Web Server</div><div style='margin-top:35vh;background:#071f3a;border-radius:24px;padding:28px;text-align:center;box-shadow:0 12px 40px #0008'><div style='font-size:18px;color:#1bd3ff'>Welcome to</div><h1 style='margin:10px 0'>Salam Web Server</h1><p style='color:#9ab5d5'>Your local server is working perfectly!</p><span style='display:inline-block;background:#0e7f55;padding:10px 18px;border-radius:30px;color:#fff'>● Online</span><div style='margin-top:22px;padding:13px;border-radius:14px;background:#03101f;color:#bcd1ea'>Fast • Secure • Local</div></div><p style='text-align:center;color:#819bb9;margin-top:25px'>Powered by Salam Web Server • Android</p></div></div></body></html>";}
    @Override public void onCreate(){super.onCreate();if(Build.VERSION.SDK_INT>=26){NotificationChannel c=new NotificationChannel("salam_server","Salam Web Server",NotificationManager.IMPORTANCE_LOW);((NotificationManager)getSystemService(NOTIFICATION_SERVICE)).createNotificationChannel(c);}}
    @Override public int onStartCommand(Intent i,int flags,int id){if(i!=null&&"STOP".equals(i.getAction())){stopServer();stopSelf();return START_NOT_STICKY;}startServer();return START_STICKY;}
    void startServer(){synchronized(WebServerService.class){if(running)return;int port=pref().getInt("port",8080);if(port<1024||port>65535)port=8080;try{socket=new ServerSocket();socket.setReuseAddress(true);socket.bind(new InetSocketAddress("0.0.0.0",port));running=true;requests=0;clients.clear();RATE.clear();startedAt=System.currentTimeMillis();log("Server started successfully on port "+port);startForeground(77,notification("Running on port "+port));new Thread(this::acceptLoop,"Salam-Accept").start();}catch(Exception e){running=false;log("START ERROR: "+e.getClass().getSimpleName()+": "+e.getMessage());}}}
    void acceptLoop(){while(running)try{Socket s=socket.accept();int max=Math.max(1,pref().getInt("maxClients",32));if(clients.size()>=max){log("Client limit reached: "+s.getInetAddress());s.close();continue;}new Thread(()->handle(s),"Salam-Client").start();}catch(Exception e){if(running)log("Accept error: "+e.getMessage());}}
    void handle(Socket s){String ip=s.getInetAddress().getHostAddress();clients.add(ip);try{s.setSoTimeout(15000);BufferedReader r=new BufferedReader(new InputStreamReader(s.getInputStream(),StandardCharsets.ISO_8859_1));String first=r.readLine();if(first==null)return;String[] p=first.split(" ",3);if(p.length<2){respond(s,400,"text/plain","Bad Request");return;}String method=p[0];String path=URLDecoder.decode(p[1].split("\\?",2)[0],"UTF-8");Map<String,String> h=new HashMap<>();String line;while((line=r.readLine())!=null&&!line.isEmpty()){int x=line.indexOf(':');if(x>0)h.put(line.substring(0,x).trim().toLowerCase(Locale.US),line.substring(x+1).trim());}requests++;if(!allowed(ip)){log(ip+" "+method+" "+path+" 403 BLOCKED");respond(s,403,"text/plain","IP blocked");return;}if(!rateAllowed(ip)){log(ip+" "+method+" "+path+" 429 RATE_LIMIT");respond(s,429,"text/plain","Too Many Requests");return;}if(!authorized(h)){log(ip+" "+method+" "+path+" 401 AUTH");auth(s);return;}File f=safe(path);if(f==null){respond(s,403,"text/plain","Forbidden");return;}if(!f.exists()){log(ip+" "+method+" "+path+" 404");respond(s,404,"text/plain","Not Found");return;}if(f.isDirectory()){File idx=new File(f,"index.html");if(idx.exists())f=idx;else{respond(s,200,"text/html",directory(f,path));log(ip+" "+method+" "+path+" 200 DIRECTORY");return;}}if("GET".equalsIgnoreCase(method)||"HEAD".equalsIgnoreCase(method)){sendFile(s,f,"HEAD".equalsIgnoreCase(method));log(ip+" "+method+" "+path+" 200");}else respond(s,405,"text/plain","Method Not Allowed");}catch(Exception e){log("Client error "+ip+": "+e.getClass().getSimpleName()+": "+e.getMessage());}finally{clients.remove(ip);try{s.close();}catch(Exception ignored){}}}
    boolean allowed(String ip){if("127.0.0.1".equals(ip)||"::1".equals(ip))return true;for(String x:pref().getString("blockIps","").split(","))if(!x.trim().isEmpty()&&ip.equals(x.trim()))return false;String allow= pref().getString("allowIps","");if(!allow.trim().isEmpty()){for(String x:allow.split(","))if(ip.equals(x.trim()))return true;return false;}return true;}
    boolean rateAllowed(String ip){int limit=Math.max(0,pref().getInt("rate",120));if(limit==0)return true;long now=System.currentTimeMillis();ArrayDeque<Long> q=RATE.computeIfAbsent(ip,k->new ArrayDeque<>());synchronized(q){while(!q.isEmpty()&&now-q.peekFirst()>=60000)q.removeFirst();if(q.size()>=limit)return false;q.addLast(now);return true;}}
    boolean authorized(Map<String,String> h){String pass=pref().getString("password","");if(pass.isEmpty())return true;String a=h.get("authorization");if(a==null||!a.startsWith("Basic "))return false;try{String z=new String(android.util.Base64.decode(a.substring(6),android.util.Base64.DEFAULT),StandardCharsets.UTF_8);int x=z.indexOf(':');return x>0&&"admin".equals(z.substring(0,x))&&pass.equals(z.substring(x+1));}catch(Exception e){return false;}}
    void auth(Socket s)throws IOException{String h="HTTP/1.1 401 Unauthorized\r\nWWW-Authenticate: Basic realm=\"Salam Web Server\"\r\nContent-Length: 0\r\nConnection: close\r\n\r\n";s.getOutputStream().write(h.getBytes(StandardCharsets.ISO_8859_1));}
    File safe(String path){try{File base=webRoot(this);File f=new File(base,path);String b=base.getCanonicalPath(),x=f.getCanonicalPath();return x.equals(b)||x.startsWith(b+File.separator)?f:null;}catch(Exception e){return null;}}
    void respond(Socket s,int code,String type,String body)throws IOException{byte[]b=body.getBytes(StandardCharsets.UTF_8);String h="HTTP/1.1 "+code+" "+reason(code)+"\r\nContent-Type: "+type+"; charset=utf-8\r\nContent-Length: "+b.length+"\r\nConnection: close\r\n\r\n";OutputStream o=s.getOutputStream();o.write(h.getBytes(StandardCharsets.ISO_8859_1));o.write(b);o.flush();}
    void sendFile(Socket s,File f,boolean head)throws IOException{String h="HTTP/1.1 200 OK\r\nContent-Type: "+mime(f.getName())+"\r\nContent-Length: "+f.length()+"\r\nConnection: close\r\n\r\n";OutputStream o=s.getOutputStream();o.write(h.getBytes(StandardCharsets.ISO_8859_1));if(!head)try(InputStream in=new FileInputStream(f)){byte[]b=new byte[16384];int n;while((n=in.read(b))>0)o.write(b,0,n);}o.flush();}
    String directory(File d,String path){StringBuilder h=new StringBuilder("<!doctype html><html><meta name=viewport content=width=device-width><body style='font-family:sans-serif;background:#03101F;color:white;padding:20px'><h2>Salam Web Server</h2>");File[]fs=d.listFiles();if(fs!=null){Arrays.sort(fs,(a,b)->a.getName().compareToIgnoreCase(b.getName()));for(File f:fs){String p=(path.endsWith("/")?path:path+"/")+f.getName();h.append("<p><a style='color:#20D5FF' href='").append(escape(p)).append("'>").append(f.isDirectory()?"📁 ":"📄 ").append(escape(f.getName())).append("</a></p>");}}return h.append("</body></html>").toString();}
    String escape(String x){return x.replace("&","&amp;").replace("<","&lt;").replace(">","&gt;").replace("\"","&quot;");}
    static String currentUrl(Context c){return "http://"+localIp(c)+":"+c.getSharedPreferences("server",MODE_PRIVATE).getInt("port",8080);}
    static String localIp(Context c){try{ConnectivityManager m=(ConnectivityManager)c.getSystemService(CONNECTIVITY_SERVICE);for(Network n:m.getAllNetworks()){LinkProperties p=m.getLinkProperties(n);if(p!=null)for(LinkAddress a:p.getLinkAddresses()){String x=a.getAddress().getHostAddress();if(x!=null&&!x.contains(":")&&!x.startsWith("127."))return x;}}}catch(Exception ignored){}return "0.0.0.0";}
    static String networkInfo(Context c){StringBuilder s=new StringBuilder();try{ConnectivityManager m=(ConnectivityManager)c.getSystemService(CONNECTIVITY_SERVICE);for(Network n:m.getAllNetworks()){LinkProperties p=m.getLinkProperties(n);if(p!=null)s.append("Interface: ").append(p.getInterfaceName()).append("\nAddresses: ").append(p.getLinkAddresses()).append("\n\n");}}catch(Exception e){s.append(e.getMessage());}return s.length()==0?"No network information":s.toString();}
    static String memoryText(Context c){ActivityManager a=(ActivityManager)c.getSystemService(ACTIVITY_SERVICE);ActivityManager.MemoryInfo m=new ActivityManager.MemoryInfo();a.getMemoryInfo(m);return fmt(m.totalMem-m.availMem)+" / "+fmt(m.totalMem);}
    static String uptime(){if(!running)return"00:00:00";long s=(System.currentTimeMillis()-startedAt)/1000;return String.format(Locale.US,"%02d:%02d:%02d",s/3600,(s%3600)/60,s%60);}
    static String logsText(){StringBuilder s=new StringBuilder();synchronized(LOGS){for(String x:LOGS)s.append(x).append('\n');}return s.toString();}
    static void clearLogs(){LOGS.clear();}
    void log(String x){synchronized(LOGS){LOGS.add(new SimpleDateFormat("HH:mm:ss",Locale.US).format(new Date())+"  "+x);while(LOGS.size()>500)LOGS.remove(0);}}
    String mime(String n){String x=n.toLowerCase(Locale.US);if(x.endsWith(".html")||x.endsWith(".htm"))return"text/html";if(x.endsWith(".css"))return"text/css";if(x.endsWith(".js"))return"application/javascript";if(x.endsWith(".json"))return"application/json";if(x.endsWith(".xml"))return"application/xml";if(x.endsWith(".txt"))return"text/plain";if(x.endsWith(".png"))return"image/png";if(x.endsWith(".gif"))return"image/gif";if(x.endsWith(".jpg")||x.endsWith(".jpeg"))return"image/jpeg";if(x.endsWith(".webp"))return"image/webp";if(x.endsWith(".svg"))return"image/svg+xml";if(x.endsWith(".ico"))return"image/x-icon";return"application/octet-stream";}
    String reason(int c){return c==200?"OK":c==400?"Bad Request":c==401?"Unauthorized":c==403?"Forbidden":c==404?"Not Found":c==405?"Method Not Allowed":c==429?"Too Many Requests":"Error";}
    static String fmt(long b){if(b<1024)return b+" B";if(b<1048576)return(b/1024)+" KB";if(b<1073741824L)return(b/1048576)+" MB";return String.format(Locale.US,"%.1f GB",b/1073741824.0);}
    Notification notification(String s){Notification.Builder b=Build.VERSION.SDK_INT>=26?new Notification.Builder(this,"salam_server"):new Notification.Builder(this);return b.setContentTitle("Salam Web Server").setContentText(s).setSmallIcon(android.R.drawable.ic_menu_view).setOngoing(true).build();}
    void stopServer(){synchronized(WebServerService.class){running=false;try{if(socket!=null)socket.close();}catch(Exception ignored){}socket=null;clients.clear();RATE.clear();log("Server stopped");try{stopForeground(true);}catch(Exception ignored){}}}
    @Override public void onDestroy(){stopServer();super.onDestroy();}
    @Override public IBinder onBind(Intent i){return null;}
}